) as v (id, panel_id, panel_name, label, programs, asset_classes, min_loan_cents, max_loan_cents, max_ltv_pct, max_ltc_pct, lien_positions, recourse, rate_min_pct, rate_max_pct, notes)
left join public.lender_panel own on own.id = v.panel_id
left join lateral (select p.id from public.lender_panel p where lower(p.name) = lower(v.panel_name) order by p.created_at limit 1) named on true
where coalesce(own.id, named.id) is not null
on conflict (id) do nothing;
